#include <iostream>
#include <vector>

// Hoan doi hai bien bang tham chieu
void swapRef(int& a, int& b) {
    int temp = a;
    a = b;
    b = temp;
}

// Thuat toan sap xep chon (Selection Sort)
void selectionSort(std::vector<int>& arr) {
    size_t n = arr.size();
    for (size_t i = 0; i + 1 < n; ++i) {
        size_t minIdx = i;
        for (size_t j = i + 1; j < n; ++j) {
            if (arr[j] < arr[minIdx]) {
                minIdx = j;
            }
        }
        if (minIdx != i) {
            swapRef(arr[i], arr[minIdx]);
        }
    }
}

int main() {
    int n;
    if (std::cin >> n) {
        std::vector<int> arr(n);
        for (int i = 0; i < n; ++i) {
            std::cin >> arr[i];
        }
        selectionSort(arr);
        for (size_t i = 0; i < arr.size(); ++i) {
            std::cout << arr[i] << (i + 1 == arr.size() ? "" : " ");
        }
        std::cout << "\n";
    }
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>

// Tinh can bac hai long nhau: sqrt(3 + sqrt(3 + ...)) voi n dau can
double nestedSqrt(int n) {
    if (n <= 1) return std::sqrt(3.0);
    return std::sqrt(3.0 + nestedSqrt(n - 1));
}

// Tinh lien phan so: 1 / (2 + 1 / (2 + ... + 1/2)) voi n dau chia
double continuedFraction(int n) {
    if (n <= 1) return 1.0 / 2.0;
    return 1.0 / (2.0 + continuedFraction(n - 1));
}

// Thap Ha Noi
void hanoi(int n, char from, char to, char aux) {
    if (n == 1) {
        std::cout << "Chuyen dia 1 tu " << from << " sang " << to << "\n";
        return;
    }
    hanoi(n - 1, from, aux, to);
    std::cout << "Chuyen dia " << n << " tu " << from << " sang " << to << "\n";
    hanoi(n - 1, aux, to, from);
}

int main() {
    int n = 3;
    std::cout << std::fixed << std::setprecision(4);
    std::cout << "S1(3) = " << nestedSqrt(n) << "\n";
    std::cout << "S2(3) = " << continuedFraction(n) << "\n";
    hanoi(3, 'A', 'C', 'B');
    return 0;
}

