// Kiem tra so nguyen to
bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

// Chuan hoa xau ky tu
std::string normalizeString(const std::string& input) {
    std::string res;
    bool inSpace = true;
    bool newWord = true;

    for (char ch : input) {
        if (std::isspace(static_cast<unsigned char>(ch))) {
            if (!inSpace) {
                res += ' ';
                inSpace = true;
                newWord = true;
            }
        } else {
            if (newWord) {
                res += static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
                newWord = false;
            } else {
                res += static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
            }
            inSpace = false;
        }
    }
    if (!res.empty() && res.back() == ' ') {
        res.pop_back();
    }
    return res;
}

int main() {
    std::string text = "   nguYen   vAn    a   ";
    std::cout << "Normalized: [" << normalizeString(text) << "]\n";
    std::cout << "Is 29 prime? " << (isPrime(29) ? "true" : "false") << "\n";
    return 0;
}
